   $this->portalAction('POD_RENDER_REVIEW_ACTION',['render_evidence_id'=>$render['id']]);self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.$t::pod_render_evidence().' WHERE id=%d',$render['id'])));
   $package=(new DigiForge\POD\ProductionAuthorizationRepository())->create($input['order_id'],(int)$render['id']);self::assertNotWPError($package);self::assertSame('REVIEW_REQUIRED',$package['state']);
   $this->portalAction('POD_PACKAGE_REVIEW_ACTION',['package_id'=>$package['id']]);$approved=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.$t::pod_authorization_packages().' WHERE id=%d',$package['id']),ARRAY_A);self::assertSame('APPROVED_PACKAGE',$approved['state']);self::assertSame(0,(int)$approved['external_execution_authorized']);self::assertSame(0,(int)$approved['external_execution_performed']);
   foreach(['personalization_submission'=>$submission,'pod_render_evidence'=>$render['id'],'pod_authorization_package'=>$package['id']] as $type=>$id)self::assertGreaterThan(0,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.$t::audit_log().' WHERE object_type=%s AND object_id=%s',$type,(string)$id)));
