 private function familyArea(string $position='front'):array {return ['position'=>$position,'decoration_method'=>'aop','width_px'=>640,'height_px'=>480,'dpi'=>300,'qa_geometry'=>['safe_zone'=>['x'=>20,'y'=>20,'width'=>600,'height'=>440],'seam_exclusions'=>[],'min_image_dpi'=>72]];}
 private function familyTemplate(array $input):array {global $wpdb;$r=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DigiForge\Database\Tables::pod_production_templates().' WHERE fingerprint=%s',$input['template_sha256']),ARRAY_A);$r['variant_ids']=json_decode($r['variant_ids'],true);$r['print_areas']=json_decode($r['print_areas'],true);return DigiForge\POD\ProductionTemplateContract::normalize($r);}
 private function familyFont():array {$font=$this->recipe()['bitmap_font'];foreach(str_split('0123456789-')as $char)$font['glyphs'][$char]=['010','101','111','101','101'];$font['id']='synthetic-layout-glyphs-not-licensed';return $font;}
 private function familyPayload(array &$input,array $schema,array $payload):void {global $wpdb;$t=DigiForge\Database\Tables::class;$hash=$input['personalization_evidence_hash'];$json=DigiForge\Orders\Validator::canonicalJson($payload);$row=$wpdb->get_row($wpdb->prepare('SELECT personalization_schema_id FROM '.$t::personalization_submissions().' WHERE payload_hash=%s',$hash),ARRAY_A);$wpdb->update($t::personalization_schemas(),['field_definitions'=>wp_json_encode($schema)],['id'=>$row['personalization_schema_id']]);$wpdb->update($t::personalization_submissions(),['canonical_payload'=>$json,'payload_hash'=>hash('sha256',$json)],['payload_hash'=>$hash]);$input['personalization_evidence_hash']=hash('sha256',$json);}
 private static int $cutoutSequence=0;
 private function familyCutout(int $order,bool $photo=false,string $style='CS01',array $options=[]):array {
  $source=tempnam(sys_get_temp_dir(),'df-source-');$mask=tempnam(sys_get_temp_dir(),'df-mask-');$sequence=static::$cutoutSequence++;$png=DigiForge\POD\RasterArtworkCodec::encode(64,64,str_repeat("\xff".chr(32+8*($sequence%20))."\x10\xff",4096));file_put_contents($source,$png);$rgba=str_repeat("\0",16384);for($y=20;$y<44;$y++)for($x=20;$x<44;$x++)$rgba[($y*64+$x)*4+3]="\xff";file_put_contents($mask,DigiForge\POD\RasterArtworkCodec::encode(64,64,$rgba));
  self::assertTrue(DigiForge\ProductFactory\AssetStorage::ensureProtectedRoot());$reference='digiforge/product-factory/design-fixture-rights-'.wp_generate_uuid4().'.txt';$doc=wp_upload_dir()['basedir'].'/'.$reference;file_put_contents($doc,'Synthetic test-only rights/consent/retention evidence; no commercial license.');$rights=['segmentation_method'=>$photo?'original_bytes':'manual_reviewed_alpha','evidence_kind'=>'SYNTHETIC_TEST_ONLY'];foreach(['rights','consent','retention']as $kind){$rights[$kind.'_reference']=$reference;$rights[$kind.'_sha256']=hash_file('sha256',$doc);}$key='fixture-'.wp_generate_uuid4();$repo=new DigiForge\POD\CustomerCutoutRepository();
  try{$record=$repo->ingest('personalized_pod',$key,$order,$source,$photo?null:$mask,$rights,$photo?'SOURCE_PHOTO':$style,$options);self::assertNotWPError($record);self::assertSame($record,$repo->ingest('personalized_pod',$key,$order,$source,$photo?null:$mask,$rights,$photo?'SOURCE_PHOTO':$style,$options));self::assertWPError($repo->assertForOrder('personalized_pod',$order,$record['result']['storage_reference']));$approved=$repo->approve('personalized_pod',$key,array_fill_keys(['missing_head','clipped_features','halo','low_contrast','fragmented_mask','low_resolution'],false));self::assertNotWPError($approved);self::assertSame('APPROVED_LOCAL_ONLY',$approved['review_state']);return [$key,$approved,$doc];}finally{unlink($source);unlink($mask);}
 }
