  $draft=DigiForge\POD\DesignFamilyLibrary::draft($this->familyTemplate($input),$id,$settings,$this->familyFont());self::assertFalse($draft['supplier_certified']);self::assertSame('REVIEW_REQUIRED',$draft['state']);$payload=[];$docs=[];
