   $bad=$draft['recipe'];$bad['design_family']['family_sha256']=hash('sha256','fake');self::assertWPError($renderer->approveRecipe($input['template_key'],1,$bad));$bad=$draft['recipe'];$bad['background']='#ff0000';self::assertWPError($renderer->approveRecipe($input['template_key'],1,$bad));
  }finally{foreach($docs as $doc)unlink($doc);}
